static double *BUF_8, *CB_8;
static void init_8(void){
  BUF_8 = (double*)xalloc((size_t)8*1152*8 + 4096);
  CB_8  = (double*)xalloc((size_t)8*1152*8 + 4096);
}
static void step_8(double* restrict buf, const double* restrict cb){
  px_8(buf);
  for(int x=0;x<8;x++){
    double* pl = buf + (size_t)x*1152;
    const double* cp = cb + (size_t)x*1152;
    py_8(pl);
    pz_8(pl, cp);
  }
}
void bench_pass_8(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_8(BUF_8);
    else if(which==1){ for(int x=0;x<8;x++) py_8(BUF_8 + (size_t)x*1152); }
    else { for(int x=0;x<8;x++) pz_8(BUF_8 + (size_t)x*1152, CB_8 + (size_t)x*1152); }
  }
}
static void conv_in_8(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*1024;
    for(int x=0;x<8;x++){
      double* dp = dst + (size_t)x*1152;
      const double* sp = s + (size_t)x*128;
      for(int r=0;r<64;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_8(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*1024;
    for(int x=0;x<8;x++){
      const double* sp = src + (size_t)x*1152;
      double* dp = d + (size_t)x*128;
      for(int r=0;r<64;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_8(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*1024;
    if(nv < 8){ memset(BUF_8, 0, (size_t)8*1152*8); memset(CB_8, 0, (size_t)8*1152*8); }
    conv_in_8(x0 + off, BUF_8, nv);
    conv_in_8(c + off, CB_8, nv);
    for(long t=1;t<=m;t++){
      step_8(BUF_8, CB_8);
      if(t==1) conv_out_8(BUF_8, o1 + off, nv);
    }
    conv_out_8(BUF_8, om + off, nv);
  }
}
