static double *BUF_13, *CB_13;
static void init_13(void){
  BUF_13 = (double*)xalloc((size_t)13*2704*8 + 4096);
  CB_13  = (double*)xalloc((size_t)13*2704*8 + 4096);
}
static void step_13(double* restrict buf, const double* restrict cb){
  px_13(buf);
  for(int x=0;x<13;x++){
    double* pl = buf + (size_t)x*2704;
    const double* cp = cb + (size_t)x*2704;
    py_13(pl);
    pz_13(pl, cp);
  }
}
void bench_pass_13(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_13(BUF_13);
    else if(which==1){ for(int x=0;x<13;x++) py_13(BUF_13 + (size_t)x*2704); }
    else { for(int x=0;x<13;x++) pz_13(BUF_13 + (size_t)x*2704, CB_13 + (size_t)x*2704); }
  }
}
static void conv_in_13(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*4394;
    for(int x=0;x<13;x++){
      double* dp = dst + (size_t)x*2704;
      const double* sp = s + (size_t)x*338;
      for(int r=0;r<169;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_13(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*4394;
    for(int x=0;x<13;x++){
      const double* sp = src + (size_t)x*2704;
      double* dp = d + (size_t)x*338;
      for(int r=0;r<169;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_13(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*4394;
    if(nv < 8){ memset(BUF_13, 0, (size_t)13*2704*8); memset(CB_13, 0, (size_t)13*2704*8); }
    conv_in_13(x0 + off, BUF_13, nv);
    conv_in_13(c + off, CB_13, nv);
    for(long t=1;t<=m;t++){
      step_13(BUF_13, CB_13);
      if(t==1) conv_out_13(BUF_13, o1 + off, nv);
    }
    conv_out_13(BUF_13, om + off, nv);
  }
}
