static double *BUF_17, *CB_17;
static void init_17(void){
  BUF_17 = (double*)xalloc((size_t)17*4736*8 + 4096);
  CB_17  = (double*)xalloc((size_t)17*4736*8 + 4096);
}
static void step_17(double* restrict buf, const double* restrict cb){
  px_17(buf);
  for(int x=0;x<17;x++){
    double* pl = buf + (size_t)x*4736;
    const double* cp = cb + (size_t)x*4736;
    py_17(pl);
    pz_17(pl, cp);
  }
}
void bench_pass_17(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_17(BUF_17);
    else if(which==1){ for(int x=0;x<17;x++) py_17(BUF_17 + (size_t)x*4736); }
    else { for(int x=0;x<17;x++) pz_17(BUF_17 + (size_t)x*4736, CB_17 + (size_t)x*4736); }
  }
}
static void conv_in_17(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*9826;
    for(int x=0;x<17;x++){
      double* dp = dst + (size_t)x*4736;
      const double* sp = s + (size_t)x*578;
      for(int r=0;r<289;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_17(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*9826;
    for(int x=0;x<17;x++){
      const double* sp = src + (size_t)x*4736;
      double* dp = d + (size_t)x*578;
      for(int r=0;r<289;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_17(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*9826;
    if(nv < 8){ memset(BUF_17, 0, (size_t)17*4736*8); memset(CB_17, 0, (size_t)17*4736*8); }
    conv_in_17(x0 + off, BUF_17, nv);
    conv_in_17(c + off, CB_17, nv);
    for(long t=1;t<=m;t++){
      step_17(BUF_17, CB_17);
      if(t==1) conv_out_17(BUF_17, o1 + off, nv);
    }
    conv_out_17(BUF_17, om + off, nv);
  }
}
