static double *BUF_23, *CB_23;
static void init_23(void){
  BUF_23 = (double*)xalloc((size_t)23*8464*8 + 4096);
  CB_23  = (double*)xalloc((size_t)23*8464*8 + 4096);
}
static void step_23(double* restrict buf, const double* restrict cb){
  px_23(buf);
  for(int x=0;x<23;x++){
    double* pl = buf + (size_t)x*8464;
    const double* cp = cb + (size_t)x*8464;
    py_23(pl);
    pz_23(pl, cp);
  }
}
void bench_pass_23(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_23(BUF_23);
    else if(which==1){ for(int x=0;x<23;x++) py_23(BUF_23 + (size_t)x*8464); }
    else { for(int x=0;x<23;x++) pz_23(BUF_23 + (size_t)x*8464, CB_23 + (size_t)x*8464); }
  }
}
static void conv_in_23(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*24334;
    for(int x=0;x<23;x++){
      double* dp = dst + (size_t)x*8464;
      const double* sp = s + (size_t)x*1058;
      for(int r=0;r<529;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_23(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*24334;
    for(int x=0;x<23;x++){
      const double* sp = src + (size_t)x*8464;
      double* dp = d + (size_t)x*1058;
      for(int r=0;r<529;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_23(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*24334;
    if(nv < 8){ memset(BUF_23, 0, (size_t)23*8464*8); memset(CB_23, 0, (size_t)23*8464*8); }
    conv_in_23(x0 + off, BUF_23, nv);
    conv_in_23(c + off, CB_23, nv);
    for(long t=1;t<=m;t++){
      step_23(BUF_23, CB_23);
      if(t==1) conv_out_23(BUF_23, o1 + off, nv);
    }
    conv_out_23(BUF_23, om + off, nv);
  }
}
