static double *BUF_36, *CB_36;
static void init_36(void){
  BUF_36 = (double*)xalloc((size_t)36*20736*8 + 4096);
  CB_36  = (double*)xalloc((size_t)36*20736*8 + 4096);
}
static void step_36(double* restrict buf, const double* restrict cb){
  px_36(buf);
  for(int x=0;x<36;x++){
    double* pl = buf + (size_t)x*20736;
    const double* cp = cb + (size_t)x*20736;
    py_36(pl);
    pz_36(pl, cp);
  }
}
void bench_pass_36(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_36(BUF_36);
    else if(which==1){ for(int x=0;x<36;x++) py_36(BUF_36 + (size_t)x*20736); }
    else { for(int x=0;x<36;x++) pz_36(BUF_36 + (size_t)x*20736, CB_36 + (size_t)x*20736); }
  }
}
static void conv_in_36(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*93312;
    for(int x=0;x<36;x++){
      double* dp = dst + (size_t)x*20736;
      const double* sp = s + (size_t)x*2592;
      for(int r=0;r<1296;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_36(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*93312;
    for(int x=0;x<36;x++){
      const double* sp = src + (size_t)x*20736;
      double* dp = d + (size_t)x*2592;
      for(int r=0;r<1296;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_36(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*93312;
    if(nv < 8){ memset(BUF_36, 0, (size_t)36*20736*8); memset(CB_36, 0, (size_t)36*20736*8); }
    conv_in_36(x0 + off, BUF_36, nv);
    conv_in_36(c + off, CB_36, nv);
    for(long t=1;t<=m;t++){
      step_36(BUF_36, CB_36);
      if(t==1) conv_out_36(BUF_36, o1 + off, nv);
    }
    conv_out_36(BUF_36, om + off, nv);
  }
}
