static double *BUF_45, *CB_45;
static void init_45(void){
  BUF_45 = (double*)xalloc((size_t)45*32400*8 + 4096);
  CB_45  = (double*)xalloc((size_t)45*32400*8 + 4096);
}
static void step_45(double* restrict buf, const double* restrict cb){
  px_45(buf);
  for(int x=0;x<45;x++){
    double* pl = buf + (size_t)x*32400;
    const double* cp = cb + (size_t)x*32400;
    py_45(pl);
    pz_45(pl, cp);
  }
}
void bench_pass_45(int which, long iters){
  for(long it=0; it<iters; it++){
    if(which==0) px_45(BUF_45);
    else if(which==1){ for(int x=0;x<45;x++) py_45(BUF_45 + (size_t)x*32400); }
    else { for(int x=0;x<45;x++) pz_45(BUF_45 + (size_t)x*32400, CB_45 + (size_t)x*32400); }
  }
}
static void conv_in_45(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    const double* s = src + (size_t)v*182250;
    for(int x=0;x<45;x++){
      double* dp = dst + (size_t)x*32400;
      const double* sp = s + (size_t)x*4050;
      for(int r=0;r<2025;r++){
        dp[r*16 + v] = sp[2*r];
        dp[r*16 + 8 + v] = sp[2*r+1];
      }
    }
  }
}
static void conv_out_45(const double* restrict src, double* restrict dst, int nv){
  for(int v=0;v<nv;v++){
    double* d = dst + (size_t)v*182250;
    for(int x=0;x<45;x++){
      const double* sp = src + (size_t)x*32400;
      double* dp = d + (size_t)x*4050;
      for(int r=0;r<2025;r++){
        dp[2*r] = sp[r*16 + v];
        dp[2*r+1] = sp[r*16 + 8 + v];
      }
    }
  }
}
static void run_45(long B, long m, const double* restrict x0, const double* restrict c, double* restrict o1, double* restrict om){
  for(long g=0; g<B; g+=8){
    int nv = (int)((B-g) < 8 ? (B-g) : 8);
    long off = g*182250;
    if(nv < 8){ memset(BUF_45, 0, (size_t)45*32400*8); memset(CB_45, 0, (size_t)45*32400*8); }
    conv_in_45(x0 + off, BUF_45, nv);
    conv_in_45(c + off, CB_45, nv);
    for(long t=1;t<=m;t++){
      step_45(BUF_45, CB_45);
      if(t==1) conv_out_45(BUF_45, o1 + off, nv);
    }
    conv_out_45(BUF_45, om + off, nv);
  }
}
#undef SC
void init_all(void){ init_6(); init_8(); init_13(); init_17(); init_23(); init_36(); init_45(); }

void run_size(int L, long B, long m, const double* x0, const double* c, double* o1, double* om){
  switch(L){
    case 6: run_6(B,m,x0,c,o1,om); break;
    case 8: run_8(B,m,x0,c,o1,om); break;
    case 13: run_13(B,m,x0,c,o1,om); break;
    case 17: run_17(B,m,x0,c,o1,om); break;
    case 23: run_23(B,m,x0,c,o1,om); break;
    case 36: run_36(B,m,x0,c,o1,om); break;
    case 45: run_45(B,m,x0,c,o1,om); break;

  }
}
